39	export function encBytes(data: Uint8Array): Buffer {
40	  const b = Buffer.from(data);
41	  const out = Buffer.alloc(4 + b.length);
42	  out.writeUInt32BE(b.length, 0);
43	  b.copy(out, 4);
44	  return out;
45	}
46	
47	export function encStr(s: string): Buffer {
48	  return encBytes(Buffer.from(s, 'utf8'));
