51	export function encUint(n: bigint | number): Buffer {
52	  const v = BigInt(n);
53	  if (v < 0n) throw new Error('cannot encode negative integer');
54	  if (v >> 256n !== 0n) throw new Error('integer exceeds 32 bytes');
55	  const out = Buffer.alloc(32);
56	  let x = v;
57	  for (let i = 31; i >= 0; i--) {
58	    out[i] = Number(x & 0xffn);
59	    x >>= 8n;
60	  }
61	  return out;
62	}
