1	import { generateKeyPair, signDigest, sha256, type Address, type KeyPair } from '../src/crypto.ts';
2	import {
3	  hashApprovalRevocation,
4	  hashBatchApproval,
5	  hashCancellation,
6	  hashPolicyChange,
7	  hashPolicyApproval,
8	  hashTransaction,
9	  hashTransactionApproval,
10	  hashTransactionBatch,
11	} from '../src/encoding.ts';
12	
13	export interface Actor extends KeyPair {}
14	
15	export function actors(n: number): Actor[] {
16	  return Array.from({ length: n }, () => generateKeyPair());
17	}
18	
19	export function addresses(list: Actor[]): Address[] {
20	  return list.map((a) => a.address);
21	}
22	
23	/** 可控时钟 */
24	export function fakeClock(start = 1000n): { now: () => bigint; advance: (s: bigint) => void; set: (t: bigint) => void } {
25	  let t = start;
26	  return {
27	    now: () => t,
28	    advance: (s: bigint) => {
29	      t += s;
30	    },
31	    set: (v: bigint) => {
32	      t = v;
33	    },
34	  };
35	}
36	
37	export interface TxParams {
38	  walletId: string;
39	  nonce: bigint;
40	  deadline: bigint;
41	  to: Address;
42	  value?: bigint;
43	  data?: Uint8Array;
44	}
45	
46	export function signTransaction(
47	  signers: Actor[],
48	  p: TxParams,
49	  opts: { mutate?: (base: TxParams) => TxParams } = {},
50	): Buffer[] {
51	  const base: TxParams = {
52	    walletId: p.walletId,
53	    nonce: p.nonce,
54	    deadline: p.deadline,
55	    to: p.to,
56	    value: p.value ?? 0n,
57	    data: p.data ?? new Uint8Array(),
58	  };
59	  const finalParams = opts.mutate ? opts.mutate(base) : base;
60	  const digest = hashTransaction({
61	    ...finalParams,
62	    value: finalParams.value ?? 0n,
63	    data: finalParams.data ?? new Uint8Array(),
64	  });
65	  return signers.map((s) => signDigest(s.privateKey, digest));
66	}
67	
68	export interface PcParams {
69	  walletId: string;
70	  version: bigint;
71	  nonce: bigint;
72	  deadline: bigint;
73	  newOwners: Address[];
74	  newConfirmations: bigint;
75	}
76	
77	export function signPolicyChange(
78	  signers: Actor[],
79	  p: PcParams,
80	  opts: { mutate?: (base: PcParams) => PcParams } = {},
81	): Buffer[] {
82	  const finalParams = opts.mutate ? opts.mutate(p) : p;
83	  const digest = hashPolicyChange(finalParams);
84	  return signers.map((s) => signDigest(s.privateKey, digest));
85	}
86	
87	export interface CancelParams {
88	  walletId: string;
89	  /** 目标任务的 digest（hex） */
90	  taskDigest: string;
91	  nonce: bigint;
92	  deadline: bigint;
93	}
94	
95	export function signCancellation(
96	  signers: Actor[],
97	  p: CancelParams,
98	  opts: { mutate?: (base: CancelParams) => CancelParams } = {},
99	): Buffer[] {
100	  const finalParams = opts.mutate ? opts.mutate(p) : p;
101	  const digest = hashCancellation(finalParams);
102	  return signers.map((s) => signDigest(s.privateKey, digest));
103	}
104	
105	export interface BatchCallParams {
106	  to: Address;
107	  value?: bigint;
108	  data?: Uint8Array;
109	}
110	
111	export interface BatchParams {
112	  walletId: string;
113	  nonce: bigint;
114	  deadline: bigint;
115	  calls: BatchCallParams[];
116	}
117	
118	export function signBatchTransaction(
119	  signers: Actor[],
120	  p: BatchParams,
121	  opts: { mutate?: (base: BatchParams) => BatchParams } = {},
122	): Buffer[] {
123	  const normalize = (q: BatchParams) => ({
124	    walletId: q.walletId,
125	    nonce: q.nonce,
126	    deadline: q.deadline,
127	    calls: q.calls.map((c) => ({
128	      to: c.to,
129	      value: c.value ?? 0n,
130	      data: c.data ?? new Uint8Array(),
131	    })),
132	  });
133	  const finalParams = opts.mutate ? opts.mutate(p) : p;
134	  const digest = hashTransactionBatch(normalize(finalParams));
135	  return signers.map((s) => signDigest(s.privateKey, digest));
136	}
