import { generateKeyPair, signDigest, sha256, type Address, type KeyPair } from '../src/crypto.ts';
import {
  hashApprovalRevocation,
  hashBatchApproval,
  hashCancellation,
  hashPolicyChange,
  hashPolicyApproval,
  hashTransaction,
  hashTransactionApproval,
  hashTransactionBatch,
} from '../src/encoding.ts';

export interface Actor extends KeyPair {}

export function actors(n: number): Actor[] {
  return Array.from({ length: n }, () => generateKeyPair());
}

export function addresses(list: Actor[]): Address[] {
  return list.map((a) => a.address);
}

/** 可控时钟 */
export function fakeClock(start = 1000n): { now: () => bigint; advance: (s: bigint) => void; set: (t: bigint) => void } {
  let t = start;
  return {
    now: () => t,
    advance: (s: bigint) => {
      t += s;
    },
    set: (v: bigint) => {
      t = v;
    },
  };
}

export interface TxParams {
  walletId: string;
  nonce: bigint;
  deadline: bigint;
  to: Address;
  value?: bigint;
  data?: Uint8Array;
}

export function signTransaction(
  signers: Actor[],
  p: TxParams,
  opts: { mutate?: (base: TxParams) => TxParams } = {},
): Buffer[] {
  const base: TxParams = {
    walletId: p.walletId,
    nonce: p.nonce,
    deadline: p.deadline,
    to: p.to,
    value: p.value ?? 0n,
    data: p.data ?? new Uint8Array(),
  };
  const finalParams = opts.mutate ? opts.mutate(base) : base;
  const digest = hashTransaction({
    ...finalParams,
    value: finalParams.value ?? 0n,
    data: finalParams.data ?? new Uint8Array(),
  });
  return signers.map((s) => signDigest(s.privateKey, digest));
}

export interface PcParams {
  walletId: string;
  version: bigint;
  nonce: bigint;
  deadline: bigint;
  newOwners: Address[];
  newConfirmations: bigint;
}

export function signPolicyChange(
  signers: Actor[],
  p: PcParams,
  opts: { mutate?: (base: PcParams) => PcParams } = {},
): Buffer[] {
  const finalParams = opts.mutate ? opts.mutate(p) : p;
  const digest = hashPolicyChange(finalParams);
  return signers.map((s) => signDigest(s.privateKey, digest));
}

export interface CancelParams {
  walletId: string;
  /** 目标任务的 digest（hex） */
  taskDigest: string;
  nonce: bigint;
  deadline: bigint;
}

export function signCancellation(
  signers: Actor[],
  p: CancelParams,
  opts: { mutate?: (base: CancelParams) => CancelParams } = {},
): Buffer[] {
  const finalParams = opts.mutate ? opts.mutate(p) : p;
  const digest = hashCancellation(finalParams);
  return signers.map((s) => signDigest(s.privateKey, digest));
}

export interface BatchCallParams {
  to: Address;
  value?: bigint;
  data?: Uint8Array;
}

export interface BatchParams {
  walletId: string;
  nonce: bigint;
  deadline: bigint;
  calls: BatchCallParams[];
}

export function signBatchTransaction(
  signers: Actor[],
  p: BatchParams,
  opts: { mutate?: (base: BatchParams) => BatchParams } = {},
): Buffer[] {
  const normalize = (q: BatchParams) => ({
    walletId: q.walletId,
    nonce: q.nonce,
    deadline: q.deadline,
    calls: q.calls.map((c) => ({
      to: c.to,
      value: c.value ?? 0n,
      data: c.data ?? new Uint8Array(),
    })),
  });
  const finalParams = opts.mutate ? opts.mutate(p) : p;
  const digest = hashTransactionBatch(normalize(finalParams));
  return signers.map((s) => signDigest(s.privateKey, digest));
}

export interface ApprovalParams {
  walletId: string;
  version: bigint;
  nonce: bigint;
  deadline: bigint;
  to: Address;
  value?: bigint;
  data?: Uint8Array;
}

export function signTransactionApproval(
  signers: Actor[],
  p: ApprovalParams,
  opts: { mutate?: (base: Required<ApprovalParams>) => ApprovalParams } = {},
): Buffer[] {
  const base: Required<ApprovalParams> = {
    walletId: p.walletId,
    version: p.version,
    nonce: p.nonce,
    deadline: p.deadline,
    to: p.to,
    value: p.value ?? 0n,
    data: p.data ?? new Uint8Array(),
  };
  const finalParams = opts.mutate ? opts.mutate(base) : base;
  const digest = hashTransactionApproval({
    ...finalParams,
    value: finalParams.value ?? 0n,
    data: finalParams.data ?? new Uint8Array(),
  });
  return signers.map((s) => signDigest(s.privateKey, digest));
}

export interface PolicyApprovalParams {
  walletId: string;
  version: bigint;
  nonce: bigint;
  deadline: bigint;
  newOwners: Address[];
  newConfirmations: bigint;
}

export function signPolicyApproval(
  signers: Actor[],
  p: PolicyApprovalParams,
  opts: { mutate?: (base: PolicyApprovalParams) => PolicyApprovalParams } = {},
): Buffer[] {
  const finalParams = opts.mutate ? opts.mutate(p) : p;
  const digest = hashPolicyApproval(finalParams);
  return signers.map((s) => signDigest(s.privateKey, digest));
}

export interface BatchApprovalParams {
  walletId: string;
  version: bigint;
  nonce: bigint;
  deadline: bigint;
  calls: BatchCallParams[];
}

export function signBatchApproval(
  signers: Actor[],
  p: BatchApprovalParams,
  opts: { mutate?: (base: BatchApprovalParams) => BatchApprovalParams } = {},
): Buffer[] {
  const normalize = (q: BatchApprovalParams) => ({
    walletId: q.walletId,
    version: q.version,
    nonce: q.nonce,
    deadline: q.deadline,
    calls: q.calls.map((c) => ({
      to: c.to,
      value: c.value ?? 0n,
      data: c.data ?? new Uint8Array(),
    })),
  });
  const finalParams = opts.mutate ? opts.mutate(p) : p;
  const digest = hashBatchApproval(normalize(finalParams));
  return signers.map((s) => signDigest(s.privateKey, digest));
}

// ---------- 统一审批撤销 ----------

export interface RevokeParams {
  walletId: string;
  /** 目标审批摘要（hex） */
  approvalDigest: string;
  nonce: bigint;
  deadline: bigint;
}

export function signApprovalRevocation(
  signers: Actor[],
  p: RevokeParams,
  opts: { mutate?: (base: RevokeParams) => RevokeParams } = {},
): Buffer[] {
  const finalParams = opts.mutate ? opts.mutate(p) : p;
  const digest = hashApprovalRevocation(finalParams);
  return signers.map((s) => signDigest(s.privateKey, digest));
}

export { sha256 };

