    InvalidCancellation,
  );
  wallet.cancelTask(policyTask.id, 3n, DEADLINE, signCancellation(ownerActors.slice(0, 4), cf2));
  assert.equal(wallet.getTask(policyTask.id)?.status, 'cancelled');
});

