+ * 返回规范化后的升序档位表（供引擎只读引用，策略变更不改变它）。
+ */
+function validateValueThresholds(
+  raw: readonly ValueThreshold[] | undefined,
+  ownerCount: number,
+  baseConfirmations: bigint,
+): NormalizedValueThreshold[] {
+  if (raw === undefined) return [];
