/**
 * 分级表中的最大档确认数（无规则钱包即全局确认数）。
 * 策略变更（直接提交、策略变更审批的创建/加签/提交/撤销及目标所有者数校验）恒按此值核对。
 */
get maxSpendingConfirmations(): bigint {
  return this.valueTiers.length === 0
    ? this.confirmations
    : this.valueTiers[this.valueTiers.length - 1]!.confirmations;
}

